from abc import ABCMeta, abstractmethod
from .telnet_cmd import generate_run_cmd, generate_kill_cmd, generate_list_cmd
from .windows_telnet import WindowsTelnetConnection


# XXX: DEPRECATED
# TODO: Remove this

class TMAAppRunner(object):
    __metaclass__ = ABCMeta

    @abstractmethod
    def run(self, path, user_profile=None, proxy_port=None,
            auto_proxy=True, auto_disconnect=True):
        pass

    @abstractmethod
    def kill(self):
        pass

    @abstractmethod
    def is_running(self):
        pass


class TelnetTMAAppRunner(TMAAppRunner):
    default_path = r"C:\Program Files (x86)\Aeroflex\TM500\V5G - NLZ 2.1.1"
    default_path += r"\Test Mobile Application\TMA.exe"
    default_imagename = 'TMA.exe'
    default_user_profile = 'Default User'
    default_proxy_port = 5003

    def __init__(self, host, username, password, timeout=10.0):
        self.timeout = timeout
        self.telnet_connection = WindowsTelnetConnection(host, username,
                                                         password, timeout)

    def run(self, path=None, user_profile=None, proxy_port=None,
            auto_proxy=True, auto_disconnect=True):
        if path is None:
            path = self.default_path
        if user_profile is None:
            user_profile = self.default_user_profile
        if proxy_port is None:
            proxy_port = self.default_proxy_port

        with self.telnet_connection as telnet:
            command = generate_run_cmd(path, user_profile=user_profile,
                                       proxy_port=proxy_port,
                                       auto_proxy=auto_proxy,
                                       auto_disconnect=auto_disconnect)
            telnet.write(command)

    def kill(self, imagename=None):
        if imagename is None:
            imagename = self.default_imagename
        with self.telnet_connection as telnet:
            command = generate_kill_cmd(imagename)
            telnet.write(command)
            self._parse_kill_response(telnet)

    def _parse_kill_response(self, telnet):
        expected_responses = ['INFO: .*\r\n', 'ERROR: .*\r\n',
                              'SUCCESS: .*\r\n']
        response = telnet.expect(expected_responses, self.timeout)
        if 'No tasks running with the specified criteria' in response[2]:
            raise ValueError('no task with the specified imagename found.')
        elif 'could not be terminated' in response[2]:
            raise RuntimeError('the task could not be terminated.')

    def is_running(self, imagename=None):
        if imagename is None:
            imagename = self.default_imagename
        with self.telnet_connection as telnet:
            command = generate_list_cmd(imagename)
            telnet.write(command)
            return self._parse_is_running_response(telnet)

    def _parse_is_running_response(self, telnet):
        expected_responses = ['Image Name.*\r\n.*\r\n', 'INFO: .*\r\n']
        response = telnet.expect(expected_responses, self.timeout)
        if response[0] == -1:
            raise RuntimeError('unexpected response from telnet session.')
        return response[0] == 0
